# Compute degree vector: d = (X @ (X.T @ 1)) - 1
d = X @ (X.T @ np.ones(n_cells)) - 1.0
d = np.maximum(d, 1e-10)  # avoid division by zero
D_inv_sqrt = 1.0 / np.sqrt(d)

# Matrix-free operator for D^{-1/2} W D^{-1/2}
import scipy.sparse.linalg as spla

def matvec(v):
    v_tilde = D_inv_sqrt * v
    return D_inv_sqrt * (X @ (X.T @ v_tilde) - v_tilde)
